import React from 'react';
import { render, screen, fireEvent } from '@testing-library/react';
import { describe, it, expect, vi } from 'vitest';
import { BookCard } from './BookCard';
import type { Book } from '../../types';

const makeBook = (overrides: Partial<Book> = {}): Book => ({
  id: 'book-1',
  title: 'The Great Gatsby',
  author: 'F. Scott Fitzgerald',
  status: 'unread',
  ...overrides,
});

describe('BookCard', () => {
  it('renders title', () => {
    render(<BookCard book={makeBook()} onClick={vi.fn()} />);
    expect(screen.getByRole('heading', { name: 'The Great Gatsby' })).toBeInTheDocument();
  });

  it('renders author', () => {
    render(<BookCard book={makeBook()} onClick={vi.fn()} />);
    expect(screen.getByText('F. Scott Fitzgerald')).toBeInTheDocument();
  });

  it('renders status badge with correct text', () => {
    render(<BookCard book={makeBook({ status: 'reading' })} onClick={vi.fn()} />);
    expect(screen.getByText('reading')).toBeInTheDocument();
  });

  it('sets data-status attribute on badge for each status variant', () => {
    const statuses: Book['status'][] = ['read', 'unread', 'reading'];
    for (const status of statuses) {
      const { unmount } = render(<BookCard book={makeBook({ status })} onClick={vi.fn()} />);
      expect(screen.getByText(status)).toHaveAttribute('data-status', status);
      unmount();
    }
  });

  it('has accessible aria-label combining title and author', () => {
    render(<BookCard book={makeBook()} onClick={vi.fn()} />);
    expect(
      screen.getByRole('button', { name: 'The Great Gatsby by F. Scott Fitzgerald' })
    ).toBeInTheDocument();
  });

  it('calls onClick with book id when clicked', () => {
    const onClick = vi.fn();
    render(<BookCard book={makeBook({ id: 'abc-123' })} onClick={onClick} />);
    fireEvent.click(screen.getByRole('button'));
    expect(onClick).toHaveBeenCalledOnce();
    expect(onClick).toHaveBeenCalledWith('abc-123');
  });

  it('calls onClick with book id when Enter is pressed', () => {
    const onClick = vi.fn();
    render(<BookCard book={makeBook({ id: 'abc-123' })} onClick={onClick} />);
    fireEvent.keyDown(screen.getByRole('button'), { key: 'Enter' });
    expect(onClick).toHaveBeenCalledOnce();
    expect(onClick).toHaveBeenCalledWith('abc-123');
  });

  it('does not call onClick when a non-Enter key is pressed', () => {
    const onClick = vi.fn();
    render(<BookCard book={makeBook()} onClick={onClick} />);
    fireEvent.keyDown(screen.getByRole('button'), { key: ' ' });
    expect(onClick).not.toHaveBeenCalled();
  });
});

