import React from 'react';
import { render, screen, fireEvent } from '@testing-library/react';
import { describe, it, expect, vi } from 'vitest';
import { ChipBar } from './ChipBar';
import type { Book } from '../../types';

const ALL_STATUSES: Book['status'][] = ['read', 'unread', 'reading'];

describe('ChipBar', () => {
  it('renders a chip for each status', () => {
    render(<ChipBar statuses={ALL_STATUSES} selected={[]} onChange={vi.fn()} />);
    expect(screen.getByRole('button', { name: 'read' })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'unread' })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'reading' })).toBeInTheDocument();
  });

  it('renders an All chip', () => {
    render(<ChipBar statuses={ALL_STATUSES} selected={[]} onChange={vi.fn()} />);
    expect(screen.getByRole('button', { name: 'All' })).toBeInTheDocument();
  });

  it('unselected chips have aria-pressed false', () => {
    render(<ChipBar statuses={ALL_STATUSES} selected={[]} onChange={vi.fn()} />);
    expect(screen.getByRole('button', { name: 'read' })).toHaveAttribute('aria-pressed', 'false');
    expect(screen.getByRole('button', { name: 'unread' })).toHaveAttribute('aria-pressed', 'false');
  });

  it('selected chips have aria-pressed true', () => {
    render(<ChipBar statuses={ALL_STATUSES} selected={['read']} onChange={vi.fn()} />);
    expect(screen.getByRole('button', { name: 'read' })).toHaveAttribute('aria-pressed', 'true');
    expect(screen.getByRole('button', { name: 'unread' })).toHaveAttribute('aria-pressed', 'false');
  });

  it('clicking an unselected chip calls onChange with it added to selection', async () => {
    const onChange = vi.fn();
    render(<ChipBar statuses={ALL_STATUSES} selected={['read']} onChange={onChange} />);
    fireEvent.click(screen.getByRole('button', { name: 'unread' }));
    expect(onChange).toHaveBeenCalledWith(expect.arrayContaining(['read', 'unread']));
  });

  it('clicking a selected chip calls onChange with it removed from selection', () => {
    const onChange = vi.fn();
    render(<ChipBar statuses={ALL_STATUSES} selected={['read', 'unread']} onChange={onChange} />);
    fireEvent.click(screen.getByRole('button', { name: 'read' }));
    const [result] = onChange.mock.calls[0];
    expect(result).not.toContain('read');
    expect(result).toContain('unread');
  });

  it('multiple chips can be pressed simultaneously', () => {
    const onChange = vi.fn();
    const { rerender } = render(
      <ChipBar statuses={ALL_STATUSES} selected={[]} onChange={onChange} />
    );
    fireEvent.click(screen.getByRole('button', { name: 'read' }));
    const afterFirst = onChange.mock.calls[0][0];

    rerender(<ChipBar statuses={ALL_STATUSES} selected={afterFirst} onChange={onChange} />);
    fireEvent.click(screen.getByRole('button', { name: 'unread' }));
    const afterSecond = onChange.mock.calls[1][0];

    expect(afterSecond).toContain('read');
    expect(afterSecond).toContain('unread');
  });

  it('All chip has aria-pressed true when no status chips are selected', () => {
    render(<ChipBar statuses={ALL_STATUSES} selected={[]} onChange={vi.fn()} />);
    expect(screen.getByRole('button', { name: 'All' })).toHaveAttribute('aria-pressed', 'true');
  });

  it('All chip has aria-pressed false when any status chip is selected', () => {
    render(<ChipBar statuses={ALL_STATUSES} selected={['read']} onChange={vi.fn()} />);
    expect(screen.getByRole('button', { name: 'All' })).toHaveAttribute('aria-pressed', 'false');
  });

  it('clicking All chip calls onChange with an empty array', () => {
    const onChange = vi.fn();
    render(<ChipBar statuses={ALL_STATUSES} selected={['read', 'reading']} onChange={onChange} />);
    fireEvent.click(screen.getByRole('button', { name: 'All' }));
    expect(onChange).toHaveBeenCalledWith([]);
  });
});

