import { renderHook, waitFor, act } from '@testing-library/react';
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { useBooks } from './useBooks';
import * as api from '../api';
import type { Book } from '../types';

const BOOKS: Book[] = [
  { id: '1', title: 'Dune', author: 'Frank Herbert', status: 'read' },
  { id: '2', title: '1984', author: 'George Orwell', status: 'unread' },
];

describe('useBooks', () => {
  beforeEach(() => {
    vi.restoreAllMocks();
  });

  afterEach(() => {
    vi.restoreAllMocks();
  });

  it('starts in loading state with no data or error', () => {
    vi.spyOn(api, 'getBooks').mockResolvedValue(BOOKS);
    const { result } = renderHook(() => useBooks());
    expect(result.current.loading).toBe(true);
    expect(result.current.data).toBeNull();
    expect(result.current.error).toBeNull();
  });

  it('transitions to loaded state with data after getBooks resolves', async () => {
    vi.spyOn(api, 'getBooks').mockResolvedValue(BOOKS);
    const { result } = renderHook(() => useBooks());
    await waitFor(() => expect(result.current.loading).toBe(false));
    expect(result.current.data).toEqual(BOOKS);
    expect(result.current.error).toBeNull();
  });

  it('transitions to error state when getBooks rejects', async () => {
    const err = new Error('fetch failed');
    vi.spyOn(api, 'getBooks').mockRejectedValue(err);
    const { result } = renderHook(() => useBooks());
    await waitFor(() => expect(result.current.loading).toBe(false));
    expect(result.current.error).toBe(err);
    expect(result.current.data).toBeNull();
  });

  it('calls getBooks exactly once on mount', async () => {
    const spy = vi.spyOn(api, 'getBooks').mockResolvedValue(BOOKS);
    const { result } = renderHook(() => useBooks());
    await waitFor(() => expect(result.current.loading).toBe(false));
    expect(spy).toHaveBeenCalledOnce();
  });

  it('does not call getBooks again on re-render', async () => {
    const spy = vi.spyOn(api, 'getBooks').mockResolvedValue(BOOKS);
    const { result, rerender } = renderHook(() => useBooks());
    await waitFor(() => expect(result.current.loading).toBe(false));
    rerender();
    expect(spy).toHaveBeenCalledOnce();
  });

  it('does not update state after unmount (no state-update warning)', async () => {
    let resolve!: (books: Book[]) => void;
    vi.spyOn(api, 'getBooks').mockReturnValue(new Promise(r => { resolve = r; }));
    const { result, unmount } = renderHook(() => useBooks());
    await act(async () => { unmount(); });
    // resolving after unmount must not throw React state-update warnings
    await act(async () => { resolve(BOOKS); });
    // state stays in its pre-unmount snapshot
    expect(result.current.loading).toBe(true);
  });
});

